import { afterEach, describe, expect, test } from "bun:test"
import { readFileSync } from "fs"
import { join } from "path"
import {
  checkInToRoom,
  fetchSharedRoom,
  fetchSharedRooms,
  readChain,
  readCloudAgent,
  readPresence,
} from "../../src/iris/shared-rooms"

// The room contract (#194603). These fixtures are the server's real responses, generated by
// fl-iris-api tests/Feature/Rooms/RoomsContractTest.php (see test/fixture/rooms-contract/README.md).
// Desktop's room client is fed them through its real fetch path, and every field the room UI draws
// must come out right — so a server rename shows up here as a wrong value, not as an empty room.

const dir = join(import.meta.dir, "..", "fixture", "rooms-contract")
const fixture = (name: string) => JSON.parse(readFileSync(join(dir, `${name}.json`), "utf-8"))

const realFetch = globalThis.fetch
afterEach(() => {
  globalThis.fetch = realFetch
})
function serve(byPath: Record<string, unknown>, seen: { url: string; init?: RequestInit }[] = []) {
  globalThis.fetch = (async (url: any, init?: RequestInit) => {
    seen.push({ url: String(url), init })
    const path = new URL(String(url)).pathname
    const body = byPath[path]
    return new Response(JSON.stringify(body ?? { message: "Not Found" }), { status: body ? 200 : 404 })
  }) as typeof fetch
  return seen
}

const ROOM = fixture("show").thread.id as string

describe("rooms contract — Desktop reads the server's real room responses (#194603)", () => {
  test("an open room: who the agents are, which one leads, the hand-off chain, who is here, the session", async () => {
    serve({ [`/api/threads/${ROOM}`]: fixture("show") })
    const r = await fetchSharedRoom(ROOM)
    expect(r.measured).toBe(true)
    const { room, agents, chain, present, sessions, messages } = r.data

    expect(room).toMatchObject({
      id: ROOM,
      name: "Launch plan",
      project: { id: expect.any(Number), name: "Pricing launch" },
      ownerName: "Alex Mayo",
      you: { role: "owner", canPost: true, canStop: true, isOwner: true },
      sessionIds: ["ses_alex"],
    })
    expect(agents.map((a) => [a.name, a.role, a.autoRespond, a.model])).toEqual([
      ["Planner", "lead", false, "gpt-4.1-nano"],
      ["Researcher", "participant", true, "gpt-4.1-nano"],
      ["Writer", "participant", false, "gpt-4.1-nano"],
    ])
    // Exactly one lead: the room UI badges it and routes the person's request to it first.
    expect(agents.filter((a) => a.role === "lead")).toHaveLength(1)
    // The server ran with turns=5, hops=2 — not readChain's fallbacks (6, 3).
    expect(chain).toEqual({ depth: 2, turns: 3, maxTurns: 5, maxHops: 2 })
    expect(present).toEqual([
      { userId: expect.any(Number), name: "Flo Rivera", state: "active", typing: true },
      { userId: expect.any(Number), name: "Alex Mayo", state: "background", typing: false },
    ])
    expect(sessions).toEqual([
      expect.objectContaining({ sessionId: "ses_alex", provider: "claude-code", machine: "alex-mbp", online: true, hostName: "Alex Mayo" }),
    ])
    expect(messages).toEqual([
      expect.objectContaining({ kind: "person", senderName: "Alex Mayo", text: "Plan the launch", deliveredTo: ["ses_alex"] }),
    ])
  })

  test("the room list as a teammate: project, rights, and the activity row (present, latest line, unread, working)", async () => {
    serve({ "/api/threads": fixture("list") })
    const r = await fetchSharedRooms()
    expect(r.measured).toBe(true)
    expect(r.data.rooms).toHaveLength(1)
    const row = r.data.rooms[0]!
    expect(row).toMatchObject({
      id: ROOM,
      name: "Launch plan",
      project: { name: "Pricing launch" },
      ownerName: "Alex Mayo",
      you: { role: "editor", canPost: true, canStop: false, isOwner: false },
      sessionIds: ["ses_alex"],
      messageCount: 1,
    })
    expect(row.activity).toEqual({
      present: [
        { userId: expect.any(Number), name: "Flo Rivera", state: "active", typing: true },
        { userId: expect.any(Number), name: "Alex Mayo", state: "background", typing: false },
      ],
      last: { kind: "person", name: "Alex Mayo", isYou: false, text: "Plan the launch", at: expect.any(String) },
      unread: 1,
      working: true,
    })
  })

  test("checking in returns who is here", async () => {
    serve({ [`/api/threads/${ROOM}/presence`]: fixture("presence") })
    const r = await checkInToRoom(ROOM, "background", false)
    expect(r.measured).toBe(true)
    expect(r.data.map((p) => [p.name, p.state, p.typing])).toEqual([
      ["Flo Rivera", "active", true],
      ["Alex Mayo", "background", false],
    ])
  })

  test("a created room, and an agent added or made lead, read back as the lead", () => {
    const created = fixture("store").thread
    expect(created.agents.map(readCloudAgent).map((a: any) => [a.name, a.role])).toEqual([
      ["Planner", "lead"],
      ["Researcher", "participant"],
    ])
    for (const name of ["add-agent", "update-agent"]) {
      const p = fixture(name).participant
      expect(readCloudAgent({ id: p.agent_id, name: "x", role: p.role, auto_respond: p.auto_respond }).role).toBe("lead")
    }
    // The readers are the ones the room UI uses; nothing here is hand-built.
    expect(readPresence(fixture("presence").present[0]).name).toBe("Flo Rivera")
    expect(readChain(fixture("show").chain)?.maxTurns).toBe(5)
  })
})
